218	// The block the executor reads. `key: value` lines, one fact per line: an agent
219	// quoting a field back must not have to parse prose, and a reader diffing two
220	// runs must see exactly what changed.
221	const block = (fields) => Object.entries(fields).map(([k, v]) => `${k}: ${v}`).join('\n');
222	
223	function done(code, fields, advice) {
224	  console.log(block(fields));
225	  if (advice) console.error(`resolve-dispatch: ${advice}`);
226	  process.exit(code);
227	}
228	
229	async function main() {
230	  const { positional, flags } = parseArgs(process.argv.slice(2));
231	  const scopeGiven = positional.length > 0;
232	  const scope = positional[0] ?? 'self';
233	  if (!SESSION_SCOPES.includes(scope)) {
234	    console.error(`resolve-dispatch: unknown scope "${scope}" — usage: node resolve-dispatch.mjs [${SESSION_SCOPES.join('|')}] [--issue-body-file <path>] [--issue-labels <csv>]`);
