241	      `${triggerError}. No trigger source names an issue, so this session cannot know which dispatch it was started for. STOP: run nothing, change nothing, comment nothing, end the session. There is NO fallback — never pick an issue by listing ${readyLabelForScope(scope)}; every dispatch in that list already has its own session, and the scheduler re-arms an unrun one on its next hourly pass.`);
242	  }
243	
244	  let { label, number, body } = trigger;
245	
246	  // The CCR handshake: the trigger named the issue, the executor fetched it over
247	  // MCP, and hands back here the two fields the environment could not carry.
248	  if (trigger.source === 'ccr') {
249	    const bodyFile = flags['issue-body-file'];
250	    const labelsCsv = flags['issue-labels'];
251	    if (bodyFile === undefined || labelsCsv === undefined) {
252	      done(EXIT.needsIssue, { dispatch: 'needs-issue', issue: number, scope, source: 'ccr', repo: trigger.repo || '(unset)' },
253	        `the CCR trigger names issue #${number} but carries neither its body nor its labels. Fetch ISSUE #${number} ALONE over MCP (its body and its current labels), write the body verbatim to a file, then re-run: node <engine>/scheduler/resolve-dispatch.mjs ${scope} --issue-body-file <path> --issue-labels <comma-separated current labels>. Do not list, select, or touch any other issue.`);
