259	      process.exit(EXIT.usage);
260	    }
261	    const labels = labelsCsv.split(',').map((l) => l.trim()).filter(Boolean);
262	    const { label: ready, error: labelError } = readyLabelAmong(labels);
263	    if (labelError) {
264	      done(EXIT.notMine, { dispatch: 'not-mine', issue: number, scope, labels: labels.join('|') || '(none)' },
